use harbor.signal;

fn entries() -> String {
    let signals = signal.today();
    let mut result = "";
    let mut i = 0;
    let mut first = true;
    while i < signals.length() {
        let s = signals.at(i);
        let rendered = match s {
            signal.Calm => "calm",
            signal.Gale(speed) => "gale:".concat(other: speed.to_text()),
            signal.Fog(density) => "fog:".concat(other: density),
        };
        if first {
            result = rendered;
            first = false;
        } else {
            result = result.concat(other: ";").concat(other: rendered);
        }
        i = i + 1;
    }
    result
}

use mill.stock;
use mill.rules;

fn lines() -> String {
    let planks = stock.inventory();
    let kept = planks.filter(|p| rules.keep(p));
    let labels = kept.map(|p| rules.label(p));
    labels.join(text: ",")
}

pub fn lines() -> String {
    let planks = mill.stock.inventory();
    var labels = [];
    var i = 0;
    while i < planks.len() {
        let p = planks.get(index: i);
        if mill.rules.keep(plank: p) {
            let label = mill.rules.label(plank: p);
            labels.push(value: label);
        }
        i = i + 1;
    }
    labels.join(text: ",")
}

