use relay.feed;

fn publish(io: Io) -> Result<Unit, Error> uses {Io.write, relay.feed.emit} {
    let frames = relay.feed.frames(io: io);
    var total = 0;
    for frame in frames {
        let decoded = match relay.feed.decode(frame: frame) {
            Some(value) => value,
            None => 0,
        };
        total = total + decoded;
    }
    relay.feed.emit(total: total, io: io)?;
    return Ok(unit);
}

use relay.feed;

pub fn publish(io: Io) -> Result<Unit, Error> uses {Io.write, relay.feed.emit} {
    let frames = relay.feed.frames();
    var total = 0;
    var i = 0;
    while i < frames.len() {
        let frame = frames.get(index: i);
        let decoded = match relay.feed.decode(frame: frame) {
            Ok(value) => value,
            Err(_) => 0,
        };
        total = total + decoded;
        i = i + 1;
    }
    relay.feed.emit(io: io, total: total)?;
    return Ok(unit);
}

